import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u04")
C = "A1-A2"

L(1, "Fruta e legumes", "de appel, de banaan, de tomaat, de aardappel…",
  ["Nomear fruta e legumes frequentes"],
  vocab=[V("v-fruit","fruit","fruta","noun","het"), V("v-groente","groente","legumes|hortaliça","noun","de","groenten"),
         V("v-banaan","banaan","banana","noun","de","bananen"), V("v-sinaasappel","sinaasappel","laranja","noun","de","sinaasappels"),
         V("v-tomaat","tomaat","tomate","noun","de","tomaten"), V("v-aardappel","aardappel","batata","noun","de","aardappels|aardappelen"),
         V("v-ui","ui","cebola","noun","de","uien")],
  ex=[("Ik eet elke dag fruit.","Como fruta todos os dias."),("Een kilo aardappels, alstublieft.","Um quilo de batatas, por favor."),("Tomaten zijn gezond.","Os tomates são saudáveis.")],
  gram=[G("g-fruit-groente","Fruit e groente","**het fruit** é incontável (como «a fruta»): *ik eet fruit*. Para peças: *een appel, twee bananen*. **groente** usa-se no singular para o conjunto (*ik eet groente*) e no plural para tipos (*verschillende groenten*). Plural de aardappel: **aardappels** ou **aardappelen** (ambos corretos).",
    [("Fruit is gezond.","A fruta é saudável.")])],
  review=["v-appel","v-eten","v-kopen","v-veel"],
  cefr=C, exs=[
    MA([("banaan","banana"),("sinaasappel","laranja"),("tomaat","tomate"),("aardappel","batata"),("ui","cebola")], "Fruta e legumes.", ["v-banaan","v-sinaasappel","v-tomaat","v-aardappel","v-ui"]),
    AR("fruit","a fruta","het", "«Het fruit» (incontável).", ["v-fruit"]),
    AR("groente","os legumes","de", "«De groente».", ["v-groente"]),
    MC("Qual é o plural de «tomaat»?", ["*tomaten","tomaats|O plural é em -en.","tomatten|Vogal longa: to-ma-ten."], "tomaat → tomaten.", ["v-tomaat"]),
    TR("pt-nl","Como fruta todos os dias.", ["Ik eet elke dag fruit","Ik eet iedere dag fruit"], "fruit sem artigo.", ["v-fruit"]),
    TR("nl-pt","Een kilo aardappels, alstublieft.", ["Um quilo de batatas, por favor"], "Sem «van»: een kilo aardappels.", ["v-aardappel"]),
    FB("Een sinaasappel is ___ .", ["oranje"], "A laranja é cor-de-laranja.", ["v-sinaasappel"], choices=["oranje","blauw","bruin"], tr="Uma laranja é cor-de-laranja."),
    LI("Ik koop bananen en uien.", ["Ik koop bananen en uien"], "Compro bananas e cebolas.", "«ui» → uien.", ["v-banaan","v-ui"]),
    FE(["Ik","eet","een","fruit."], 2, "(retirar)", "«fruit» é incontável: ik eet fruit (ou: ik eet een appel).", ["v-fruit"]),
    WO("Os tomates são vermelhos.", ["Tomaten","zijn","rood"], "Plural sem artigo.", ["v-tomaat","v-rood"]),
  ], diff=1, mins=5)

L(2, "Bebidas", "Sumo, água com gás, refrigerantes e o que pedir.",
  ["Nomear e pedir bebidas"],
  vocab=[V("v-sap","sap","sumo","noun","het",note="sinaasappelsap = sumo de laranja; jus d'orange também se usa."), V("v-frisdrank","frisdrank","refrigerante","noun","de","frisdranken"),
         V("v-bruisend-water","bruisend water","água com gás","expression",note="Também «spa rood» (marca) na fala."), V("v-warm","warm","quente","adjective"),
         V("v-kraanwater","kraanwater","água da torneira","noun","het",note="A água da torneira nos Países Baixos é de excelente qualidade.")],
  ex=[("Een glas sinaasappelsap, alstublieft.","Um copo de sumo de laranja, por favor."),("Wilt u water met of zonder bubbels?","Quer água com ou sem gás?"),("Kraanwater is gratis.","A água da torneira é grátis.")],
  review=["v-water","v-thee","v-koffie","v-bier","v-wijn","v-melk","v-koud"],
  cefr=C, exs=[
    MA([("sap","sumo"),("frisdrank","refrigerante"),("bruisend water","água com gás"),("kraanwater","água da torneira")], "Bebidas.", ["v-sap","v-frisdrank","v-bruisend-water","v-kraanwater"]),
    AR("sap","o sumo","het", "«Het sap».", ["v-sap"]),
    AR("frisdrank","o refrigerante","de", "«De frisdrank».", ["v-frisdrank"]),
    TR("pt-nl","Um sumo de laranja, por favor.", ["Een [sinaasappelsap|jus d'orange](,) [alstublieft|alsjeblieft]"], "sinaasappel + sap.", ["v-sap"]),
    TR("nl-pt","Wilt u water met of zonder bubbels?", ["Quer água com ou sem gás"], "bubbels = bolhas.", ["v-water"]),
    MC("Quer chá quente. Qual é a palavra para «quente»?", ["*warm","koud|«koud» = frio.","heet|«heet» é «muito quente» (a escaldar) — também possível, mas «warm» é o normal."], "warm = quente.", ["v-warm"]),
    FB("Thee drink ik ___, niet koud.", ["warm"], "warm ≠ koud.", ["v-warm"], choices=["warm","rood","lekker koud"], tr="Bebo o chá quente, não frio."),
    DL([("Empregado","Wat wilt u drinken?","O que quer beber?"),("Cliente","")], ["*Een spa rood, alstublieft.","Ik ben water.|Não faz sentido.","Graag gedaan.|Isso é «de nada»."], "«spa rood» = água com gás (marca usada como nome comum).", ["v-bruisend-water"]),
    LI("Een kop thee, graag.", ["Een kop thee(,) graag"], "Uma chávena de chá, por favor.", "«graag» no fim de um pedido = por favor.", ["v-thee","v-graag"]),
    WO("Bebo água ao almoço.", ["Bij","de","lunch","drink","ik","water"], "Inversão depois de «bij de lunch».", ["v-water"], alt=["Ik drink water bij de lunch"]),
  ], diff=1, mins=5)

L(3, "Gostar e não gostar", "lekker, vies, ik eet graag…, ik houd van…",
  ["Dizer o que gosta e não gosta de comer e beber"],
  vocab=[V("v-vies","vies","nojento|que sabe mal","adjective"), V("v-graag-verb","graag","gostar de (com verbo)","adverb",note="Ik eet graag vis = gosto de comer peixe."),
         V("v-lusten","lusten","gostar de (comida)","verb",note="Ik lust geen vis = não gosto de peixe."), V("v-zoet","zoet","doce","adjective"), V("v-zout","zout","salgado|sal","adjective")],
  ex=[("Ik eet graag vis.","Gosto de comer peixe."),("Ik drink niet graag koffie.","Não gosto muito de beber café."),("Ik houd van chocolade!","Adoro chocolate!"),("Dat is vies!","Isso sabe mal!")],
  gram=[G("g-graag","Graag para gostos","A forma mais natural de dizer que se gosta de fazer algo é **verbo + graag**: *ik eet **graag** vis* (gosto de comer peixe). Negativo: *ik eet **niet graag** vis*. **houden van** é mais forte (adorar, amar): *ik houd van kaas*. Para comida também se usa **lusten**: *ik lust geen spruitjes*.",
    [("Ik fiets graag.","Gosto de andar de bicicleta.")],
    "O português usa um verbo («gostar»); o neerlandês prefere um advérbio junto do verbo principal.")],
  review=["v-lekker","v-eten","v-drinken","v-vis","v-houden-van"],
  cefr=C, exs=[
    MA([("lekker","saboroso"),("vies","que sabe mal"),("zoet","doce"),("zout","salgado")], "Sabores.", ["v-lekker","v-vies","v-zoet","v-zout"]),
    TR("pt-nl","Gosto de comer peixe.", ["Ik eet graag vis"], "verbo + graag.", ["v-graag-verb","v-vis"], bank=["Ik","eet","graag","vis","houd","van"]),
    TR("pt-nl","Não gosto (muito) de beber café.", ["Ik drink niet graag koffie"], "niet graag.", ["v-graag-verb"]),
    TR("nl-pt","Ik houd van chocolade!", ["Adoro chocolate","Gosto muito de chocolate"], "houden van = adorar.", ["v-houden-van"]),
    MC("Qual é a ordem correta?", ["*Ik eet graag kaas.","Ik graag eet kaas.|Verbo em 2.º: ik eet graag kaas."], "Verbo em 2.º: ik eet graag kaas.", ["v-graag-verb"]),
    MC("Prova algo de que não gosta nada. O que diz (informal)?", ["*Bah, dat is vies!","Lekker!|«lekker» = saboroso.","Gefeliciteerd!|Isso é «parabéns»."], "vies = sabe mal.", ["v-vies"]),
    FB("Ik ___ geen spruitjes.", ["lust"], "lusten = gostar (de comer); geralmente na negativa.", ["v-lusten"], choices=["lust","houd","graag"], tr="Não gosto de couves-de-bruxelas."),
    LI("Wat eet je graag?", ["Wat eet je graag"], "De que gostas de comer?", "Pergunta com graag.", ["v-graag-verb"]),
    DL([("Sanne","Hou je van zoet?","Gostas de doces?"),("Pedro","")], ["*Ja, heel graag! Vooral chocolade.","Ja, ik ben zoet.|Diz «sou doce».","Nee, het is zout.|Não responde bem."], "«Hou je van…?» (forma oral de houd).", ["v-zoet","v-houden-van"]),
    SW("Diga duas coisas que gosta e uma que não gosta de comer ou beber.", ["Ik eet graag [vis|kaas|fruit](.) Ik drink graag [koffie|thee](.) Ik eet niet graag [vlees|vis]"],
       ["Usa «verbo + graag»","Usa «niet graag» para o que não gosta","Verbo em 2.º lugar"], 8, "Modelo: «Ik eet graag vis en ik drink graag thee. Ik eet niet graag spruitjes.»", ["v-graag-verb"]),
  ], diff=2, mins=6)

L(4, "Pão, queijo e o que se põe no pão", "kaas, boter, hagelslag, vlees, kip.",
  ["Nomear alimentos típicos neerlandeses e proteínas"],
  vocab=[V("v-kaas","kaas","queijo","noun","de","kazen"), V("v-boter","boter","manteiga","noun","de"), V("v-hagelslag","hagelslag","granulado de chocolate","noun","de",note="Clássico do pequeno-almoço neerlandês, no pão com manteiga."),
         V("v-vlees","vlees","carne","noun","het"), V("v-kip","kip","frango","noun","de"), V("v-vegetarisch","vegetarisch","vegetariano","adjective"),
         V("v-broodje","broodje","pãozinho|sandes","noun","het","broodjes")],
  ex=[("Een broodje kaas, alstublieft.","Uma sandes de queijo, por favor."),("Ik eet geen vlees, ik ben vegetarisch.","Não como carne, sou vegetariano."),("Brood met boter en hagelslag.","Pão com manteiga e granulado de chocolate.")],
  gram=[G("g-broodje","Broodje …","Para sandes diz-se **broodje** + recheio, sem preposição: *een broodje kaas*, *een broodje kip*. **het vlees** é incontável: *ik eet vlees*. Nos Países Baixos o pão (com queijo, fiambre ou hagelslag) é a base do pequeno-almoço e do almoço.",
    [("een broodje gezond","uma sandes com queijo, fiambre e salada")],
    "Em português «sandes DE queijo»; em neerlandês, «broodje kaas».")],
  review=["v-brood","v-melk","v-ei","v-vis","v-geen"],
  cefr=C, exs=[
    MA([("kaas","queijo"),("boter","manteiga"),("vlees","carne"),("kip","frango"),("hagelslag","granulado de chocolate")], "No pão e à mesa.", ["v-kaas","v-boter","v-vlees","v-kip","v-hagelslag"]),
    AR("vlees","a carne","het", "«Het vlees».", ["v-vlees"]),
    AR("broodje","a sandes","het", "Diminutivo -je → het.", ["v-broodje"]),
    TR("pt-nl","Uma sandes de queijo, por favor.", ["Een broodje kaas(,) [alstublieft|alsjeblieft]"], "Sem preposição.", ["v-broodje","v-kaas"]),
    TR("pt-nl","Não como carne, sou vegetariano.", ["Ik eet geen vlees(,) ik ben vegetarisch"], "geen vlees.", ["v-vlees","v-vegetarisch"]),
    FE(["Een","broodje","van","kip,","alstublieft."], 2, "(retirar)", "Sem «van»: een broodje kip.", ["v-broodje"]),
    MC("O que é «hagelslag»?", ["*Granulado de chocolate para pôr no pão","Um tipo de queijo|Queijo é «kaas».","Uma bebida quente|Não."], "Muito típico ao pequeno-almoço.", ["v-hagelslag"]),
    TR("nl-pt","Ik eet brood met kaas.", ["Como pão com queijo"], "met = com.", ["v-kaas"]),
    LI("Is dit vegetarisch?", ["Is dit vegetarisch"], "Isto é vegetariano?", "Pergunta útil no restaurante.", ["v-vegetarisch"]),
    CO("text","O pequeno-almoço do Tom", "Tom ontbijt elke dag met twee boterhammen. Op de eerste boterham doet hij kaas, op de tweede hagelslag. Hij drinkt een glas melk. Vlees eet hij 's ochtends nooit.",
       [("O que põe o Tom na segunda fatia?", ["*Granulado de chocolate","Queijo","Manteiga de amendoim"]),("O que bebe?", ["*Leite","Café","Sumo"])],
       "boterham = fatia de pão.", ["v-kaas","v-hagelslag"]),
  ], diff=2, mins=5)

L(5, "O que comes?", "Revisão: comida, bebida e gostos.",
  ["Falar dos hábitos alimentares"],
  ex=[("Ik eet graag fruit en groente, maar ik lust geen kaas.","Gosto de fruta e legumes, mas não gosto de queijo.")],
  review=["v-graag-verb","v-lekker","v-vies","v-fruit","v-groente","v-kaas","v-vlees","v-sap","v-vegetarisch"],
  cefr=C, exs=[
    MA([("groente","legumes"),("fruit","fruta"),("vlees","carne"),("sap","sumo")], "Revisão.", ["v-groente","v-fruit","v-vlees","v-sap"]),
    AR("kaas","o queijo","de", "«De kaas».", ["v-kaas"]),
    TR("pt-nl","Gosto de beber sumo de laranja.", ["Ik drink graag [sinaasappelsap|jus d'orange]"], "verbo + graag.", ["v-graag-verb","v-sap"]),
    TR("nl-pt","Het eten is heel lekker!", ["A comida está muito boa","A comida é muito saborosa","A comida está deliciosa"], "lekker = saboroso.", ["v-lekker"]),
    FE(["Ik","eet","niet","vlees."], 2, "geen", "Substantivo sem artigo: geen vlees.", ["v-vlees","v-geen"]),
    FB("Hij is ___: hij eet geen vlees en geen vis.", ["vegetarisch"], "vegetarisch.", ["v-vegetarisch"], choices=["vegetarisch","zoet","vies"], tr="Ele é vegetariano: não come carne nem peixe."),
    LI("Wat drink je het liefst?", ["Wat drink je het liefst"], "O que preferes beber?", "het liefst = de preferência.", ["v-drinken"]),
    DL([("Médico","Eet u gezond?","Come de forma saudável?"),("Ana","")], ["*Ja, ik eet elke dag groente en fruit.","Ja, ik eet elke dag chips.|Não é muito saudável!","Nee, ik ben gezond.|Contraditório."], "gezond = saudável.", ["v-groente","v-fruit"]),
    CO("text","Gostos da família", "In ons gezin eet iedereen iets anders. Mijn man is vegetarisch. Mijn dochter eet graag pasta, maar ze lust geen groente. Mijn zoon houdt van vis. En ik? Ik eet alles!",
       [("Quem não come carne?", ["*O marido","A filha","O filho"]),("De que não gosta a filha?", ["*De legumes","De massa","De peixe"])],
       "iets anders = algo diferente; alles = tudo.", ["v-vegetarisch","v-lusten"]),
    SW("Descreva o que come num dia normal (pequeno-almoço, almoço e jantar).", ["'s [Ochtends|ochtends] eet ik brood met kaas(.) Bij de lunch eet ik een broodje(.) 's [Avonds|avonds] eet ik vis met aardappels"],
       ["Três momentos do dia","Comidas com o artigo certo quando necessário","Inversão depois de expressões de tempo"], 10, "Compare com o modelo.", ["v-eten"]),
  ], diff=2, mins=6)

W()
